                })?;
                let args_value: serde_json::Value = serde_json::from_str(&json_args).map_err(|e| {
                    zbus::fdo::Error::InvalidArgs(format!("invalid JSON args: {}", e))
                })?;
                validator.validate(&args_value).map_err(|e| {
                    zbus::fdo::Error::InvalidArgs(format!("args do not conform to method schema: {}", e))
                })?;
