        let token = SessionToken::generate_secure();

        let session = Session {
            id: session_id.clone(),
            identity_id: identity.id,
            token: token.clone(),
            created_at: chrono::Utc::now(),
            expires_at: chrono::Utc::now() + chrono::Duration::hours(24),
            last_activity: chrono::Utc::now(),
        };

