            "INSERT INTO sessions (id, identity_id, token, created_at, expires_at) VALUES (?, ?, ?, ?, ?)",
            session.id,
            session.identity_id,
            session.token.as_str(),
            session.created_at,
            session.expires_at
        )
        .execute(&self.db_pool)
        .await?;

        Ok(token)
    }
