use super::*;

#[tokio::test]
async fn test_unknown_method_rejected() {
    let _scope = TestScope::new();
    let mut _state = State::new();
    let mut _routes = HashMap::new();n
    // Create plugin schema with only GetStatus method
    let plugin_id = "test_plugin".to_string();
    let mut methods = HashMap::new();
    methods.insert(
        "GetStatus".to_string(),
        json!({"type": "object", "properties": {}, "required": []}),
    );
    let route = PluginRoute {
        plugin_id: plugin_id.clone(),
        dbus_path: format!("/org/opdbus/v1/plugins/{}", plugin_id),
        dbus_destination: "org.opdbus.v1".to_string(),
        dbus_interface: format!("org.opdbus.v1.Plugin.{}", plugin_id),
        methods,
        signals: vec![],
        properties: HashMap::new(),
    };
    _routes.insert(plugin_id.clone(), route);

    // Create SchemaBackedInterface with test route
    let mut iface = SchemaBackedInterface::with_shm_state_dir(
        plugin_id.clone(),
        _routes.remove(&plugin_id).unwrap(),
        "/tmp",
    );

    // Attempt to call unknown method SetStatus
    let result = iface.call("SetStatus".to_string(), "{}".to_string()).await;
    assert!(
        result.is_err(),
        "Unknown method should be rejected with UnknownMethod error"
    );
    match result {
        Err(zbus::fdo::Error::UnknownMethod(_)) => {},
        _ => panic!("Expected UnknownMethod error"),
    }
}

